when.condition:
@{
                var token = context.Request.Headers.GetValueOrDefault("Authorization","").Split(Convert.ToChar(32))[1].AsJwt();
                var roles = token != null && token.Claims.ContainsKey("roles") ? token.Claims["roles"] : null;
                return roles == null || !roles.Contains("MCP.Read");
            }

set-variable.value:
@{
            var token = context.Request.Headers.GetValueOrDefault("Authorization","").Split(Convert.ToChar(32))[1].AsJwt();
            return token != null && token.Claims.ContainsKey("oid") && token.Claims["oid"] != null && token.Claims["oid"].Length > 0 ? token.Claims["oid"][0] : string.Empty;
        }

return-response.set-body:
@{
                        return new JObject(
                            new JProperty("jsonrpc", "2.0"),
                            new JProperty("id", context.Variables["mcpId"]),
                            new JProperty("result", new JObject(
                                new JProperty("protocolVersion", "2024-11-05"),
                                new JProperty("capabilities", new JObject(
                                    new JProperty("tools", new JObject())
                                )),
                                new JProperty("serverInfo", new JObject(
                                    new JProperty("name", "sobject-reads"),
                                    new JProperty("version", "1.0.0")
                                ))
                            ))
                        ).ToString();
                    }

@{
                        var tools = new JArray(
                            new JObject(
                                new JProperty("name", "getObjectSchema"),
                                new JProperty("description", "Returns Salesforce object schema"),
                                new JProperty("inputSchema", new JObject(
                                    new JProperty("type", "object"),
                                    new JProperty("properties", new JObject(
                                        new JProperty("objects", new JObject(new JProperty("type", "string")))
                                    )),
                                    new JProperty("required", new JArray())
                                )),
                                new JProperty("annotations", new JObject(new JProperty("readOnlyHint", true)))
                            ),
                            new JObject(
                                new JProperty("name", "soqlQuery"),
                                new JProperty("description", "Runs a SOQL query"),
                                new JProperty("inputSchema", new JObject(
                                    new JProperty("type", "object"),
                                    new JProperty("properties", new JObject(
                                        new JProperty("q", new JObject(new JProperty("type", "string")))
                                    )),
                                    new JProperty("required", new JArray("q"))
                                )),
                                new JProperty("annotations", new JObject(new JProperty("readOnlyHint", true)))
                            ),
                            new JObject(
                                new JProperty("name", "find"),
                                new JProperty("description", "Runs a SOSL text search"),
                                new JProperty("inputSchema", new JObject(
                                    new JProperty("type", "object"),
                                    new JProperty("properties", new JObject(
                                        new JProperty("s", new JObject(new JProperty("type", "string")))
                                    )),
                                    new JProperty("required", new JArray("s"))
                                )),
                                new JProperty("annotations", new JObject(new JProperty("readOnlyHint", true)))
                            ),
                            new JObject(
                                new JProperty("name", "getUserInfo"),
                                new JProperty("description", "Returns identity for the authenticated user"),
                                new JProperty("inputSchema", new JObject(
                                    new JProperty("type", "object"),
                                    new JProperty("properties", new JObject()),
                                    new JProperty("required", new JArray())
                                )),
                                new JProperty("annotations", new JObject(new JProperty("readOnlyHint", true)))
                            ),
                            new JObject(
                                new JProperty("name", "listRecentSobjectRecords"),
                                new JProperty("description", "Retrieves recently viewed records"),
                                new JProperty("inputSchema", new JObject(
                                    new JProperty("type", "object"),
                                    new JProperty("properties", new JObject(
                                        new JProperty("sobject", new JObject(new JProperty("type", "string")))
                                    )),
                                    new JProperty("required", new JArray("sobject"))
                                )),
                                new JProperty("annotations", new JObject(new JProperty("readOnlyHint", true)))
                            ),
                            new JObject(
                                new JProperty("name", "getRelatedRecords"),
                                new JProperty("description", "Fetches child records"),
                                new JProperty("inputSchema", new JObject(
                                    new JProperty("type", "object"),
                                    new JProperty("properties", new JObject(
                                        new JProperty("sobject", new JObject(new JProperty("type", "string"))),
                                        new JProperty("id", new JObject(new JProperty("type", "string"))),
                                        new JProperty("relationship", new JObject(new JProperty("type", "string")))
                                    )),
                                    new JProperty("required", new JArray("sobject", "id", "relationship"))
                                )),
                                new JProperty("annotations", new JObject(new JProperty("readOnlyHint", true)))
                            )
                        );

                        return new JObject(
                            new JProperty("jsonrpc", "2.0"),
                            new JProperty("id", context.Variables["mcpId"]),
                            new JProperty("result", new JObject(
                                new JProperty("tools", tools)
                            ))
                        ).ToString();
                    }

@{
                                var args = JObject.Parse((string)context.Variables["toolArgs"]);
                                var objectName = args?["objects"]?.ToString();
                                if (!string.IsNullOrEmpty(objectName) && objectName.ToUpper() == "ACCOUNT") {
                                    return new JObject(
                                        new JProperty("jsonrpc", "2.0"),
                                        new JProperty("id", context.Variables["mcpId"]),
                                        new JProperty("result", new JObject(
                                            new JProperty("content", new JArray(
                                                new JObject(
                                                    new JProperty("type", "text"),
                                                    new JProperty("text", "[{\"message\":\"sObject type 'Account' is not supported.\",\"errorCode\":\"INVALID_TYPE\"}]")
                                                )
                                            )),
                                            new JProperty("isError", true)
                                        ))
                                    ).ToString();
                                }
                                var mockData = "[{\"name\":\"Account\",\"label\":\"Account\",\"keyPrefix\":\"001\"},{\"name\":\"Contact\",\"label\":\"Contact\",\"keyPrefix\":\"003\"},{\"name\":\"Opportunity\",\"label\":\"Opportunity\",\"keyPrefix\":\"006\"}]";
                                return new JObject(
                                    new JProperty("jsonrpc", "2.0"),
                                    new JProperty("id", context.Variables["mcpId"]),
                                    new JProperty("result", new JObject(
                                        new JProperty("content", new JArray(
                                            new JObject(
                                                new JProperty("type", "text"),
                                                new JProperty("text", mockData)
                                            )
                                        )),
                                        new JProperty("isError", false)
                                    ))
                                ).ToString();
                            }

@{
                                var args = JObject.Parse((string)context.Variables["toolArgs"]);
                                var queryText = args?["q"]?.ToString() ?? string.Empty;
                                if (queryText.ToUpper().Contains("FROM ACCOUNT")) {
                                    return new JObject(
                                        new JProperty("jsonrpc", "2.0"),
                                        new JProperty("id", context.Variables["mcpId"]),
                                        new JProperty("result", new JObject(
                                            new JProperty("content", new JArray(
                                                new JObject(
                                                    new JProperty("type", "text"),
                                                    new JProperty("text", "[{\"message\":\"sObject type 'Account' is not supported.\",\"errorCode\":\"INVALID_TYPE\"}]")
                                                )
                                            )),
                                            new JProperty("isError", true)
                                        ))
                                    ).ToString();
                                }
                                var mockRecords = "[{\"Id\":\"001xx000001XyzAAA\",\"Name\":\"Acme Corp\"},{\"Id\":\"001xx000001XyzAAB\",\"Name\":\"Global Industries\"}]";
                                return new JObject(
                                    new JProperty("jsonrpc", "2.0"),
                                    new JProperty("id", context.Variables["mcpId"]),
                                    new JProperty("result", new JObject(
                                        new JProperty("content", new JArray(
                                            new JObject(
                                                new JProperty("type", "text"),
                                                new JProperty("text", mockRecords)
                                            )
                                        )),
                                        new JProperty("isError", false)
                                    ))
                                ).ToString();
                            }

@{
                                var userOid = (string)context.Variables["userOid"];
                                var identity = "{\"user_id\":\"005xx000001XyzAAA\",\"username\":\"" + userOid + "@mock\",\"display_name\":\"Mock User\"}";
                                return new JObject(
                                    new JProperty("jsonrpc", "2.0"),
                                    new JProperty("id", context.Variables["mcpId"]),
                                    new JProperty("result", new JObject(
                                        new JProperty("content", new JArray(
                                            new JObject(
                                                new JProperty("type", "text"),
                                                new JProperty("text", identity)
                                            )
                                        )),
                                        new JProperty("isError", false)
                                    ))
                                ).ToString();
                            }

@{
                                var mockFind = "[{\"attributes\":{\"type\":\"Contact\"},\"Id\":\"003xx000001XyzAAA\",\"Name\":\"Mock Contact\"}]";
                                return new JObject(
